        + '<div class="lsub">' + L('仓位比', 'Weight') + '</div></div>'
        + '<div class="lval"><div class="v1">' + fmtPct1(a2.pct) + '%</div>'
        + '<div class="v2">' + L('点击修改', 'tap to edit') + '</div></div>'
