    + '<div class="hintbar" style="margin:0">' + L('到定投日当天 9:00 自动推送本地通知 · 只记标的与日期，不记金额', 'Local notification at 09:00 on the DCA day · ticker and date only, no amounts') + '</div>';
  document.getElementById('sheetBody').innerHTML = body;
