/* ---------- 定投仓位比：按市场温度给出本期建议投入比例 ---------- */
var POS_KEY = 'fuley.posRatio.v1';
var posCfg = loadJSON(POS_KEY, null) || {};
if (!posCfg || typeof posCfg !== 'object') posCfg = {};
if (posCfg.override != null && !(posCfg.override >= 20 && posCfg.override <= 100)) posCfg.override = null;
function savePosCfg() { saveJSON(POS_KEY, posCfg); }

/* 分位：小于等于 v 的样本占比（0-100） */
function pctRank(vals, v) {
  if (!vals || !vals.length || !isFinite(v)) return null;
  var c = 0;
  for (var i = 0; i < vals.length; i++) if (vals[i] <= v) c++;
  return c / vals.length * 100;
}
/* 市场温度 = VIX 分位（恐惧情绪越高→温度越高）；仓位比 = 100 - 温度，钳制 20%～100% */
function dcaPosModel() {
  var vixArr = [];
  if (typeof VIX_DATA !== 'undefined' && VIX_DATA.length) {
    for (var j = Math.max(0, VIX_DATA.length - 252); j < VIX_DATA.length; j++) {
      var vv = Number(VIX_DATA[j][1]);
      if (isFinite(vv)) vixArr.push(vv);
    }
  }
  var vixNow = vixArr.length ? vixArr[vixArr.length - 1] : null;
  var vixPct = vixNow != null ? pctRank(vixArr, vixNow) : null;

  var temp = vixPct != null ? vixPct : 50;
  var auto = Math.max(20, Math.min(100, Math.round((100 - temp) / 10) * 10));
  var manual = posCfg.override != null;
  return {
    vixPct: vixPct, vix: vixNow, temp: temp,
    auto: auto, use: manual ? posCfg.override : auto, manual: manual, ok: vixPct != null
  };
}
/* ---------- 标的仓位占比（手动维护：股票名称 + 占比） ---------- */
var ALLOC_KEY = 'fuley.alloc.v1';
var allocs = loadJSON(ALLOC_KEY, []);
if (!Array.isArray(allocs)) allocs = [];
var editAllocId = null;
function saveAllocs() { saveJSON(ALLOC_KEY, allocs); }
/* 仓位 / 仓位比：拖动 ≡ 上下排序（指针事件，手机与电脑通用） */
function allocHandle(id) {
  return '<span class="drag-h" data-id="' + id + '" title="' + L('拖动排序', 'Drag to reorder') + '"'
    + ' onclick="event.stopPropagation()">\u2261</span>';
}
var allocDrag = null;
function bindAllocDrag() {
  ['planList', 'posAlloc'].forEach(function (boxId) {
    var box = document.getElementById(boxId);
    if (!box) return;
    Array.prototype.forEach.call(box.querySelectorAll('.drag-h'), function (h) {
      if (h.__dhb) return;
      h.__dhb = true;
      h.addEventListener('pointerdown', function (e) {
        var row = h.closest('.lrow');
        if (!row) return;
        e.preventDefault();
        e.stopPropagation();
        allocDrag = {
          row: row, wrap: row.parentNode, startY: e.clientY, moved: false,
          pointerId: e.pointerId
        };
        row.classList.add('dragging');
        try { h.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
      });
      h.addEventListener('pointermove', function (e) {
        if (!allocDrag || allocDrag.pointerId !== e.pointerId) return;
        if (Math.abs(e.clientY - allocDrag.startY) < 4) return;
        allocDrag.moved = true;
        e.preventDefault();
        var rows = Array.prototype.slice.call(allocDrag.wrap.querySelectorAll('.lrow'));
        var ref = null;
        for (var i = 0; i < rows.length; i++) {
          var r = rows[i];
          if (r === allocDrag.row) continue;
          var rect = r.getBoundingClientRect();
          if (e.clientY < rect.top + rect.height / 2) { ref = r; break; }
        }
        if (ref) {
          if (ref.previousSibling !== allocDrag.row) allocDrag.wrap.insertBefore(allocDrag.row, ref);
        } else if (allocDrag.wrap.lastElementChild !== allocDrag.row) {
          allocDrag.wrap.appendChild(allocDrag.row);
        }
      });
      ['pointerup', 'pointercancel'].forEach(function (t) {
        h.addEventListener(t, function (e) {
          if (!allocDrag || allocDrag.pointerId !== e.pointerId) return;
          var d = allocDrag;
          allocDrag = null;
          d.row.classList.remove('dragging');
          try { h.releasePointerCapture(e.pointerId); } catch (err) { /* ignore */ }
          if (!d.moved) return;
          /* 按新的 DOM 顺序重排 allocs */
          var order = Array.prototype.slice.call(d.wrap.querySelectorAll('.lrow'))
            .map(function (r) { return r.getAttribute('data-id'); });
          var map = {}, next = [];
          allocs.forEach(function (a) { map[a.id] = a; });
          order.forEach(function (id) {
            if (map[id]) { next.push(map[id]); delete map[id]; }
          });
          allocs.forEach(function (a) { if (map[a.id]) next.push(a); });
          allocs = next;
          saveAllocs();
          renderPlans();
          renderPosRatio();
          toast(L('顺序已保存', 'Order saved'));
        });
      });
    });
  });
}
function fmtPct1(v) { var n = Number(v) || 0; return n % 1 ? n.toFixed(1) : String(n); }
