(function initSeedNotes() {
  var had = null;
  try { had = localStorage.getItem(NOTES_KEY); } catch (e) { had = 'x'; }
  if (had === null) {
    // 首次使用：写入示例笔记（与原型一致）
    notes = { red: [], green: [], case: [] };
    ['red', 'green', 'case'].forEach(function (k) {
      SEED_NOTES[k].forEach(function (it) {
        var o = { date: it.date, text: it.text, en: it.en };
        if (it.dateEn) o.dateEn = it.dateEn;
        notes[k].push(o);
      });
    });
    saveNotes();
    return;
  }
  // 已存在数据：给与示例同文的笔记补英文（只匹配预置文本，用户自写内容不动）
  var changed = false;
  var norm = function (t) { return String(t == null ? '' : t).replace(/\s+/g, ''); };
  ['red', 'green', 'case'].forEach(function (k) {
    (notes[k] || []).forEach(function (n) {
      if (n.en) return;
      var hit = null;
      SEED_NOTES[k].forEach(function (it) { if (norm(it.text) === norm(n.text)) hit = it; });
      if (hit) {
        n.en = hit.en;
        if (hit.dateEn && !n.dateEn) n.dateEn = hit.dateEn;
        changed = true;
      }
    });
  });
  if (changed) saveNotes();
})();

function saveNotes() { saveJSON(NOTES_KEY, notes); }
function noteKind() { return lampDir === 1 ? 'red' : lampDir === -1 ? 'green' : 'case'; }
function noteBoxId(kind) { return kind === 'red' ? 'noteListRed' : kind === 'green' ? 'noteListGreen' : 'noteListCase'; }
function noteLabel(kind) { return kind === 'red' ? L('红线', 'Red') : kind === 'green' ? L('绿线', 'Green') : L('案例', 'Case'); }
function noteColor(kind) { return kind === 'red' ? 'var(--up)' : kind === 'green' ? 'var(--down)' : 'var(--accent)'; }
function renderNoteList(kind) {
  var box = document.getElementById(noteBoxId(kind));
  if (!box) return;
  var arr = notes[kind];
  if (!arr.length) {
    box.innerHTML = '<div class="empty">' + L('暂无' + noteLabel(kind) + '记录', 'No ' + noteLabel(kind).toLowerCase() + ' entries yet') + '</div>';
    return;
  }
  var en = !!(window.FuleyI18N && window.FuleyI18N.isEn && window.FuleyI18N.isEn());
  var html = '';
  arr.forEach(function (n, i) {
    var dt = (en && n.dateEn) ? n.dateEn : n.date;
    html += '<div class="notecard">'
      + '<div class="nd"><span class="lamprow">'
      + '<span class="lamp" style="background:' + noteColor(kind) + '"></span>'
      + '<span class="lt ' + (kind === 'red' ? 'red' : kind === 'green' ? 'green' : '') + '">' + noteLabel(kind) + '</span>'
      + '<span class="dt">' + esc(dt) + '</span></span>'
      + '<button class="del" title="' + L('删除', 'Delete') + '" onclick="delNote(\'' + kind + '\',' + i + ')">×</button></div>'
      + '<div class="nt"></div></div>';
  });
  box.innerHTML = html;
  box.querySelectorAll('.notecard .nt').forEach(function (el, i) {
    // 预写笔记带 en 字段：按当前语言取文本；用户自写内容仍走 raw 原文保护
    var src = (en && arr[i].en) ? arr[i].en : arr[i].text;
    el.textContent = (window.FuleyI18N && window.FuleyI18N.raw) ? window.FuleyI18N.raw(src) : src;
  });
}
function renderNotes() { renderNoteList('red'); renderNoteList('green'); renderNoteList('case'); }
function lampSeg(btn, dir) {
  lampDir = dir;
  btn.parentElement.querySelectorAll('button').forEach(function (b) {
    b.classList.remove('on', 'red', 'green', 'rule');
  });
  btn.classList.add('on');
  if (dir === 1) btn.classList.add('red');
  else if (dir === -1) btn.classList.add('green');
  else if (dir === 2) btn.classList.add('rule');
  // 交易法则页只隐藏录入框与底部计数（注意：不能隐藏 .editor，它包含 lampSeg 切换条本身）
  var showEditor = dir !== 2;
  var taEl = document.getElementById('noteInput');
  if (taEl) taEl.style.display = showEditor ? '' : 'none';
  var efEl = document.querySelector('#view-notes .efoot');
  if (efEl) efEl.style.display = showEditor ? '' : 'none';
  document.getElementById('noteListRed').style.display = dir === 1 ? '' : 'none';
  document.getElementById('noteListGreen').style.display = dir === -1 ? '' : 'none';
  document.getElementById('noteListCase').style.display = dir === 0 ? '' : 'none';
  var rc = document.getElementById('noteRuleChart');
  var rl = document.getElementById('noteListRule');
  if (rc) rc.style.display = dir === 2 ? '' : 'none';
  if (rl) rl.style.display = dir === 2 ? '' : 'none';
  if (dir === 2) {
    // 复位子tab到右侧
    var sub = document.querySelectorAll('#ruleSubSeg button');
    sub.forEach(function (b) { b.classList.remove('on'); });
    if (sub[0]) sub[0].classList.add('on');
    var rr = document.getElementById('ruleRight'), lr = document.getElementById('ruleLeft');
    if (rr) rr.style.display = '';
    if (lr) lr.style.display = 'none';
  }
}
function ruleSub(btn, which) {
  btn.parentElement.querySelectorAll('button').forEach(function (b) { b.classList.remove('on'); });
  btn.classList.add('on');
  document.getElementById('ruleRight').style.display = which === 'right' ? '' : 'none';
  document.getElementById('ruleLeft').style.display = which === 'left' ? '' : 'none';
}
function addNote() {
  var ta = document.getElementById('noteInput');
  var v = (ta.value || '').trim();
  if (!v) { toast(L('先写点什么再保存', 'Write something first')); return; }
  var kind = noteKind();
  notes[kind].unshift({ date: dateStr(new Date()), text: v });
  saveNotes();
  renderNoteList(kind);
  // 自动切到刚保存颜色的列表，录入即所见
  var segBtns = document.querySelectorAll('#lampSeg button');
  var segIdx = kind === 'red' ? 0 : kind === 'green' ? 1 : 2;
  if (segBtns[segIdx]) lampSeg(segBtns[segIdx], lampDir);
  ta.value = '';
  document.getElementById('noteCount').textContent = '0 / 500';
  toast(L('已录入' + noteLabel(kind), 'Saved to ' + noteLabel(kind)));
}
function delNote(kind, i) {
  notes[kind].splice(i, 1);
  saveNotes();
  renderNoteList(kind);
  toast('已删除');
}

