var VIX_LEVELS = [
  { max: 13,  name: '平静',   color: '#1a9e5c', state: '市场几乎无恐慌 · 贪婪区', act: '定投照常，切忌追高' },
  { max: 17,  name: '温和',   color: '#5cb85c', state: '轻微波动 · 情绪平稳',     act: '维持正常定投节奏' },
  { max: 25,  name: '正常',   color: '#dfa32a', state: '中等波动 · 多空分歧',     act: '留意潜在加仓机会' },
  { max: 35,  name: '高波动', color: '#e07b39', state: '恐慌升温 · 抛压加大',     act: '可启动分批加仓' },
  { max: 999, name: '极端',   color: '#e04a4a', state: '极度恐慌 · 危机模式',     act: '历史性机会区，果断出手' }
];
function vixLevelOf(v) {
  for (var i = 0; i < VIX_LEVELS.length; i++) if (v < VIX_LEVELS[i].max) return VIX_LEVELS[i];
  return VIX_LEVELS[VIX_LEVELS.length - 1];
}
function vixDateFull(d) { return '20' + d.slice(0, 2) + '-' + d.slice(2, 4) + '-' + d.slice(4, 6); }
function vixLast() { return VIX_DATA[VIX_DATA.length - 1]; }
function vixPrev() { return VIX_DATA[VIX_DATA.length - 2] || VIX_DATA[VIX_DATA.length - 1]; }
/* 极坐标映射：VIX 0 → 180°，50 → 0°（左半圆到右半圆） */
function vixPt(v, r) {
  var a = Math.PI * (1 - Math.min(50, Math.max(0, v)) / 50);
  return [170 + r * Math.cos(a), 170 - r * Math.sin(a)];
}
function vixArc(v0, v1, r) {
  var p0 = vixPt(v0, r), p1 = vixPt(v1, r);
  return 'M ' + p0[0].toFixed(2) + ' ' + p0[1].toFixed(2) + ' A ' + r + ' ' + r + ' 0 0 1 ' + p1[0].toFixed(2) + ' ' + p1[1].toFixed(2);
}
function vixGaugeSvg(v) {
  var s = '<svg viewBox="0 0 340 210" xmlns="http://www.w3.org/2000/svg">';
  var b = [0, 13, 17, 25, 35, 50];
  for (var i = 0; i < 5; i++) {
    var on = v >= b[i] && v < b[i + 1];
    s += '<path d="' + vixArc(b[i], b[i + 1], 128) + '" fill="none" stroke="' + VIX_LEVELS[i].color +
      '" stroke-width="15" opacity="' + (on ? 1 : .3) + '"/>';
  }
  for (var t = 0; t <= 50; t += 5) {
    var p1 = vixPt(t, 112), p2 = vixPt(t, t % 10 === 0 ? 102 : 107);
    s += '<line x1="' + p1[0].toFixed(1) + '" y1="' + p1[1].toFixed(1) + '" x2="' + p2[0].toFixed(1) +
      '" y2="' + p2[1].toFixed(1) + '" stroke="var(--sub)" stroke-width="1.2" opacity=".55"/>';
  }
  for (var t2 = 0; t2 <= 50; t2 += 10) {
    var p = vixPt(t2, 91);
    s += '<text x="' + p[0].toFixed(1) + '" y="' + (p[1] + 3.5).toFixed(1) + '" text-anchor="middle" font-size="9.5" font-weight="700" fill="var(--sub)">' + t2 + '</text>';
  }
  var lv = vixLevelOf(v);
  s += '<text x="170" y="42" text-anchor="middle" font-size="15" font-weight="800" fill="' + lv.color + '">' + lv.name + '</text>';
  s += '<text x="170" y="60" text-anchor="middle" font-size="10" font-weight="500" fill="var(--sub)">' + lv.state + '</text>';
  var tip = vixPt(v, 102), fl = vixPt(v + 3.4, 13), fr = vixPt(v - 3.4, 13);
  s += '<polygon points="' + tip[0].toFixed(1) + ',' + tip[1].toFixed(1) + ' ' + fl[0].toFixed(1) + ',' + fl[1].toFixed(1) +
    ' ' + fr[0].toFixed(1) + ',' + fr[1].toFixed(1) + '" fill="var(--ink)" opacity=".85"/>';
  s += '<circle cx="170" cy="170" r="7" fill="var(--ink)"/>';
  s += '<text x="170" y="150" text-anchor="middle" font-size="30" font-weight="800" fill="var(--ink)">' + v.toFixed(2) + '</text>';
  s += '<text x="170" y="168" text-anchor="middle" font-size="9.5" font-weight="600" fill="var(--sub)">VIX</text>';
  return s + '</svg>';
}
function vixSparkSvg(year) {
  var W = 300, H = 100, PT = 8, PB = 16, PL = 2, PR = 2;
  var mn = Infinity, mx = -Infinity;
  year.forEach(function (r) { if (r[1] < mn) mn = r[1]; if (r[1] > mx) mx = r[1]; });
  if (!isFinite(mn)) { mn = 0; mx = 1; }
  if (mx - mn < 2) { mn -= 1; mx += 1; }
  function X(i) { return PL + (W - PL - PR) * i / Math.max(1, year.length - 1); }
  function Y(v) { return PT + (H - PT - PB) * (1 - (v - mn) / (mx - mn)); }
  var d = '';
  year.forEach(function (r, i) {
    d += (i ? ' L ' : 'M ') + X(i).toFixed(1) + ' ' + Y(r[1]).toFixed(1);
  });
  var area = d + ' L ' + X(year.length - 1).toFixed(1) + ' ' + (H - PB) + ' L ' + X(0).toFixed(1) + ' ' + (H - PB) + ' Z';
  var lc = vixLevelOf(year[year.length - 1][1]).color;
  var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="none">';
  s += '<defs><linearGradient id="vixgrad" x1="0" y1="0" x2="0" y2="1">' +
    '<stop offset="0" stop-color="' + lc + '" stop-opacity=".28"/>' +
    '<stop offset="1" stop-color="' + lc + '" stop-opacity=".02"/></linearGradient></defs>';
  [25, 35].forEach(function (lv) {
    if (lv > mn && lv < mx) {
      s += '<line x1="' + PL + '" y1="' + Y(lv).toFixed(1) + '" x2="' + (W - PR) + '" y2="' + Y(lv).toFixed(1) +
        '" stroke="var(--line)" stroke-width="1" stroke-dasharray="4 3"/>';
    }
  });
  s += '<path d="' + area + '" fill="url(#vixgrad)"/>';
  s += '<path d="' + d + '" fill="none" stroke="' + lc + '" stroke-width="1.8" stroke-linejoin="round"/>';
  s += '<circle cx="' + X(year.length - 1).toFixed(1) + '" cy="' + Y(year[year.length - 1][1]).toFixed(1) + '" r="3" fill="' + lc + '"/>';
  s += '<text x="' + (W - PR) + '" y="' + (H - 3) + '" text-anchor="end" font-size="9" font-weight="600" fill="var(--sub)">' + mn.toFixed(0) + ' ~ ' + mx.toFixed(0) + '</text>';
  return s + '</svg>';
}
function renderVix() {
  if (!document.getElementById('vixPane')) return;     // 面板已下线
  if (!VIX_DATA.length) return;
  var last = vixLast(), prev = vixPrev();
  var v = last[1], chg = v - prev[1], pct = prev[1] ? chg / prev[1] * 100 : 0;
  var lv = vixLevelOf(v);
  document.getElementById('vixAsOf').textContent = '截至 ' + vixDateFull(last[0]);
  document.getElementById('vixNow').textContent = v.toFixed(2);
  var chgEl = document.getElementById('vixChg');
  chgEl.textContent = (chg >= 0 ? '+' : '') + chg.toFixed(2) + ' (' + (chg >= 0 ? '+' : '') + pct.toFixed(1) + '%)';
  chgEl.className = 'vix-chg ' + (chg > 0 ? 'up' : chg < 0 ? 'down' : 'flat');
  document.getElementById('vixDot').style.background = lv.color;
  document.getElementById('vixLvName').textContent = lv.name;
  document.getElementById('vixLvState').textContent = '· ' + lv.state;
  document.getElementById('vixGauge').innerHTML = vixGaugeSvg(v);
  var year = VIX_DATA.slice(-252);
  var below = 0;
  year.forEach(function (r) { if (r[1] <= v) below++; });
  document.getElementById('vixRange').textContent = '一年区间 ' + Math.min.apply(null, year.map(function (r) { return r[1]; })).toFixed(0) +
    '–' + Math.max.apply(null, year.map(function (r) { return r[1]; })).toFixed(0) +
    ' · 当前分位 ' + Math.round(below / year.length * 100) + '%';
  document.getElementById('vixSpark').innerHTML = vixSparkSvg(year);
  var h = '';
  VIX_LEVELS.forEach(function (L, i) {
    var lo = i === 0 ? 0 : VIX_LEVELS[i - 1].max;
    var range = lo + '–' + (L.max > 900 ? '∞' : L.max);
    h += '<div class="vix-lvrow' + (L === lv ? ' cur' : '') + '"><span class="vix-dot" style="background:' + L.color + '"></span>' +
      '<span class="vix-lvname">' + L.name + '</span><span class="vix-lvrange">' + range + '</span>' +
      '<div class="vix-lvinfo"><div class="vix-lvstate">' + L.state + '</div><div class="vix-lvact">' + L.act + '</div></div></div>';
  });
  document.getElementById('vixLevels').innerHTML = h;
}
/* App 内（Capacitor 原生）增量拉取 FRED 最新日线，浏览器环境用内置数据 */
function vixFetchUpdate() {
  try {
    if (!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform())) return;
    var CH = window.CapacitorHttp || (window.Capacitor.Plugins && window.Capacitor.Plugins.CapacitorHttp);
    if (!CH || !CH.get) return;
    var from = vixDateFull(vixLast());
    CH.get({ url: 'https://fred.stlouisfed.org/graph/fredgraph.csv?id=VIXCLS&cosd=' + from })
      .then(function (r) {
        var txt = (r && r.data) || '';
        if (typeof txt !== 'string' || txt.indexOf('observation_date') < 0) return;
        var rows = txt.trim().split(/\r?\n/).slice(1), changed = false;
        rows.forEach(function (line) {
          var p = line.split(',');
          if (p.length < 2 || !p[1] || p[1] === '.') return;
          var d = p[0].replace(/-/g, '').slice(2), val = Number(p[1]);
          if (!isFinite(val) || val <= 0) return;
          if (d > vixLast()[0]) { VIX_DATA.push([d, val]); changed = true; }
          else if (d === vixLast()[0] && VIX_DATA[VIX_DATA.length - 1][1] !== val) { VIX_DATA[VIX_DATA.length - 1][1] = val; changed = true; }
        });
        if (changed) {
          lsSet('fuley.vix.v1', JSON.stringify(VIX_DATA.slice(-400)));
          if (curHomePane === 'vix') renderVix();
          if (curTab === 'plan' && curPlanPane === 'pos') renderPosRatio();
        }
      }).catch(function () {});
  } catch (e) {}
}
function vixRestore() {
  try {
    var raw = lsGet('fuley.vix.v1');
    if (!raw) return;
    var arr = JSON.parse(raw);
    if (!Array.isArray(arr)) return;
    arr.forEach(function (r) {
      if (!Array.isArray(r) || r.length !== 2) return;
      var d = String(r[0]), val = Number(r[1]);
      if (!isFinite(val) || val <= 0) return;
      if (d > vixLast()[0]) VIX_DATA.push([d, val]);
    });
  } catch (e) {}
}

