function eventsOn(ds) {
  var out = CAL_EVENTS.filter(function (e) { return e.d === ds; });
  calCustom.forEach(function (c, i) { if (c.d === ds) out.push({ t: c.t, title: c.title, note: '自定义', idx: i }); });
  return out;
}
var calMonths = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function renderCal() {
  document.getElementById('calTitle').textContent = L(calY + '年' + (calM + 1) + '月', calMonths[calM] + ' ' + calY);
  var first = new Date(calY, calM, 1);
  var startDow = (first.getDay() + 6) % 7; // 周一=0
  var daysInMonth = new Date(calY, calM + 1, 0).getDate();
  var today = new Date();
  var todayStr = today.getFullYear() + '-' + (today.getMonth() + 1 < 10 ? '0' : '') + (today.getMonth() + 1) + '-' + (today.getDate() < 10 ? '0' : '') + today.getDate();
  var html = L('一,二,三,四,五,六,日', 'M,T,W,T,F,S,S').split(',').map(function (w) { return '<div class="cal-wd">' + w + '</div>'; }).join('');
  var monthHasErn = CAL_EVENTS.some(function (e) {
    return e.t === 'earnings' && e.d.slice(0, 7) === (calY + '-' + (calM + 1 < 10 ? '0' : '') + (calM + 1));
  });
  var b;
  for (b = 0; b < startDow; b++) html += '<div class="cal-day blank"></div>';
  for (var day = 1; day <= daysInMonth; day++) {
    var ds = calY + '-' + (calM + 1 < 10 ? '0' : '') + (calM + 1) + '-' + (day < 10 ? '0' : '') + day;
    var evs = eventsOn(ds);
    var isErn = evs.some(function (e) { return e.t === 'earnings'; });   // 财报日 → 底部标红
    var ringStyle = evs.length ? ' style="--ring:' + CAL_TYPES[evs[0].t].color + '"' : '';
    html += '<button class="cal-day' + (ds === todayStr ? ' today' : '') + (ds === calSel ? ' sel' : '') + (isErn ? ' ern' : '') + '" onclick="calSelect(\'' + ds + '\')">'
      + '<span class="dnum' + (evs.length ? ' ring' : '') + '"' + ringStyle + '>' + day + '</span>'
      + '</button>';
  }
  var grid = document.getElementById('calGrid');
  grid.className = 'cal-grid' + (monthHasErn ? ' ern-month' : '');
  grid.innerHTML = html;
  renderMonthList();
  document.getElementById('calSelTitle').textContent = calSel + ' 事件';
  renderCalEvents();
}
function renderCalEvents() {
  var evs = eventsOn(calSel);
  var box = document.getElementById('calEvents');
  if (!evs.length) {
    box.innerHTML = '<div class="cal-empty">当天没有日程 · 可点击下方按钮标记</div>';
    return;
  }
  var html = '';
  evs.forEach(function (e) {
    var tp = CAL_TYPES[e.t] || CAL_TYPES.custom;
    html += '<div class="cal-row' + (e.t === 'custom' ? ' custom' : '') + '">'
      + '<span class="ct-chip" style="background:' + tp.color + '">' + tp.label + '</span>'
      + '<div class="ct-t"></div>'
      + '<span class="ct-n">' + esc(evNote(e)) + '</span>'
      + (e.t === 'custom' ? '<button class="ct-del" title="删除" onclick="delCalEvent(' + e.idx + ')">×</button>' : '')
      + '</div>';
  });
  box.innerHTML = html;
  box.querySelectorAll('.cal-row').forEach(function (row, i) {
    var it = evs[i];
    row.querySelector('.ct-t').textContent = it.zh ? L(it.zh, it.en) : it.title;
  });
}
function evNote(e) {
  if (!e) return '';
  if (e.ne) return L(e.nz || e.note || '', e.ne);
  return calNoteText(e.note);
}
function calNoteText(n) {
  if (n === '预计') return L('预计', 'est.');
  if (n === '已确认') return L('已确认', 'confirmed');
  if (n === '自定义') return L('自定义', 'custom');
  return n || '';
}
/* 月重点：按月取日程清单（含自定义），月历下方同时显示本月与下月 */
function monthEventsOf(y, m) {
  var pre = y + '-' + (m + 1 < 10 ? '0' : '') + (m + 1);
  var out = [];
  CAL_EVENTS.forEach(function (e) {
    if (String(e.d).indexOf(pre) === 0) out.push({ d: e.d, t: e.t, zh: e.zh, en: e.en, title: e.title, note: e.note, nz: e.nz, ne: e.ne });
  });
  calCustom.forEach(function (c) {
    if (String(c.d).indexOf(pre) === 0) out.push({ d: c.d, t: c.t, title: c.title, note: '自定义' });
  });
  out.sort(function (a, b) { return a.d < b.d ? -1 : a.d > b.d ? 1 : 0; });
  return out;
}
function monthEvents() { return monthEventsOf(calY, calM); }

function monthBlockHTML(y, m, isNext) {
  var evs = monthEventsOf(y, m);
  var hasErn = evs.some(function (e) { return e.t === 'earnings'; });
  var title = isNext
    ? L('下月重点', 'Next month')
    : L((m + 1) + ' 月重点', calMonths[m] + ' highlights');
  var meta = isNext
    ? L((m + 1) + ' 月 · ' + evs.length + ' 件', calMonths[m] + ' · ' + evs.length + ' items')
    : evs.length + L(' 件', ' items');
  var h = '<div class="cal-mt' + (isNext ? ' next' : '') + '">' + title
    + (hasErn ? '<span class="cal-mtag">' + L('财报季', 'earnings season') + '</span>' : '')
    + '<em>' + meta + '</em></div>';
  if (!evs.length) {
    h += '<div class="cal-empty">' + (isNext
      ? L('下月暂无预置日程', 'Nothing scheduled next month')
      : L('本月没有预置日程 · 可点下方「标记事件」补充', 'Nothing scheduled this month')) + '</div>';
    return h;
  }
  evs.forEach(function (e) {
    var tp = CAL_TYPES[e.t] || CAL_TYPES.custom;
    h += '<div class="cal-row' + (e.t === 'custom' ? ' custom' : '') + '" onclick="calSelect(\'' + e.d + '\')">'
      + '<span class="ct-chip" style="background:' + tp.color + '">' + tp.label + '</span>'
      + '<div class="ct-t">' + e.d.slice(5) + ' ' + esc(e.zh ? L(e.zh, e.en) : (e.title || '')) + '</div>'
      + '<span class="ct-n">' + esc(evNote(e)) + '</span>'
      + '</div>';
  });
  return h;
}
function renderMonthList() {
  var box = document.getElementById('calMonthList');
  if (!box) return;
  box.innerHTML = monthBlockHTML(calY, calM, false);
  var nbox = document.getElementById('calNextList');
  if (nbox) {
    var ny = calY, nm = calM + 1;
    if (nm > 11) { nm = 0; ny++; }
    nbox.innerHTML = monthBlockHTML(ny, nm, true);
  }
}
function calSelect(ds) { calSel = ds; renderCal(); }
function calMove(delta) {
  calM += delta;
  if (calM < 0) { calM = 11; calY--; }
  if (calM > 11) { calM = 0; calY++; }
  renderCal();
}
function openCalEvent() {
  sheetMode = 'calev';
  document.getElementById('sheetSave').textContent = '标记';
  document.getElementById('sheetTitle').textContent = '标记事件';
  document.getElementById('sheetBody').innerHTML =
    '<div class="field"><label>日期</label><input type="date" id="calDate" value="' + calSel + '"></div>'
    + '<div class="field"><label>事件标题</label><input type="text" id="calTitleInput" maxlength="60" placeholder="如：NVDA 回调到 180 复盘"></div>'
    + '<div class="field"><label>类型</label><select id="calType">'
    + '<option value="custom">自定义</option><option value="earnings">财报</option>'
    + '<option value="econ">经济</option><option value="vote">选举</option></select></div>';
  showSheet();
}
function calSave() {
  var d = document.getElementById('calDate').value || '';
  var title = (document.getElementById('calTitleInput').value || '').trim();
  var t = document.getElementById('calType').value || 'custom';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) { toast('请选择日期'); return; }
  if (!title) { toast('请填写事件标题'); return; }
  calCustom.push({ d: d, t: t, title: title });
  saveCalCustom();
  calSel = d;
  calY = Number(d.slice(0, 4));
  calM = Number(d.slice(5, 7)) - 1;
  renderCal();
  closeSheet();
  toast('已标记 ' + d);
}
function delCalEvent(i) {
  calCustom.splice(i, 1);
  saveCalCustom();
  renderCal();
  toast('已删除');
}

/* ---------- 授权许可（试用期 / 一年期授权） ---------- */
function licStateText(st) {
  if (st.status === 'licensed') return L('已授权 · 剩 ' + st.daysLeft + ' 天', 'Licensed · ' + st.daysLeft + ' days left');
  if (st.status === 'trial') return L('试用中 · 剩 ' + st.daysLeft + ' 天', 'Trial · ' + st.daysLeft + ' days left');
  return L('已过期 · 点击续签', 'Expired · tap to renew');
}
function renderLicenseState() {
  var row = document.getElementById('licState');
  if (row) row.textContent = licStateText(window.FuleyLicense.state());
  var st = window.FuleyLicense.state();
  if (st.status === 'expired') showLicLock(); else hideLicLock();
}
function showLicLock() {
  var st = window.FuleyLicense.state();
  document.getElementById('llDev').textContent = window.FuleyLicense.getDeviceId();
  var t = document.getElementById('llTitle');
  var s = document.getElementById('llSub');
  if (t) t.textContent = (st.trial ? L('试用期已结束', 'Trial ended') : L('授权已到期', 'License expired'));
  if (s) s.textContent = (st.trial ? L('输入激活码继续使用浮乐 · 激活后授权 1 年', 'Enter a code to keep using Fuley · 1-year license')
    : L('一年一签，请续签后继续使用（' + (st.expireDate || '') + ' 已到期）',
      'Renewed yearly — please renew to continue (expired ' + (st.expireDate || '') + ')'));
  document.getElementById('licLock').classList.add('on');
}
function hideLicLock() {
  document.getElementById('licLock').classList.remove('on');
}
function openLicense() {
  sheetMode = 'license';
  var st = window.FuleyLicense.state();
  var totalDays = (st.status === 'trial') ? window.FuleyLicense.TRIAL_DAYS : window.FuleyLicense.LIC_DAYS;
  var pct = Math.round((totalDays - st.daysLeft) / totalDays * 100);
  document.getElementById('sheetSave').textContent = L('激活', 'Activate');
  document.getElementById('sheetTitle').textContent = L('授权许可', 'License');
  document.getElementById('sheetBody').innerHTML =
    '<div class="lic-state' + (st.status === 'expired' ? ' locked' : '') + '">'
    + '<div class="ls-t">' + (st.status === 'trial' ? L('试用期', 'Trial') : L('正式授权', 'Licensed')) + '<span>' + licStateText(st) + '</span></div>'
    + '<div class="lic-bar"><i style="width:' + Math.max(0, Math.min(100, pct)) + '%"></i></div>'
    + '<div class="ls-d">' + (st.expireDate ? L('到期日 ' + st.expireDate, 'Expires ' + st.expireDate) : '') + '</div>'
    + '</div>'
    + '<div class="field"><label>设备识别码（长按复制，发给作者获取激活码）</label>'
    + '<div class="lic-dev">' + window.FuleyLicense.getDeviceId() + '</div></div>'
    + '<div class="field"><label>激活码</label><input type="text" id="licInput" placeholder="FULEY-XXXX-XXXX-XXXX-XXXX" autocomplete="off"></div>'
    + '<div class="hintbar" style="margin:0">激活即授权 1 年（一年一签）· 到期前 15 天会提醒续签</div>';
  showSheet();
}
function activateLicense() {
  var v = (document.getElementById('licInput').value || '').trim();
  if (!v) { toast('请输入激活码'); return; }
  window.FuleyLicense.activate(v).then(function (r) {
    toast(r.msg);
    if (r.ok) { hideLicLock(); renderLicenseState(); closeSheet(); }
  });
}
function llActivate() {
  var v = (document.getElementById('llCode').value || '').trim();
  if (!v) { toast('请输入激活码'); return; }
  window.FuleyLicense.activate(v).then(function (r) {
    toast(r.msg);
    if (r.ok) { hideLicLock(); renderLicenseState(); }
  });
}

/* ---------- 我的页：导出 / 备份 / 恢复 / 账号 ---------- */
var meUser = null;            // null = 未登录；{ account, name } = 已登录
var ACCOUNT_KEY = 'fuley.account.v1';
var SESSION_KEY = 'fuley.session.v1';
var authMode = 'login';       // register | login
function loadAccount() { return loadJSON(ACCOUNT_KEY, null); }
function loadSession() { return loadJSON(SESSION_KEY, null); }
function djb2(s) { var h = 5381; for (var i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return ('00000000' + h.toString(16)).slice(-8); }
function hashPass(p) {
  var s = 'fuley.salt.' + p;
  var c = window.crypto || (typeof crypto !== 'undefined' ? crypto : null);
  if (c && c.subtle && c.subtle.digest) {
    return c.subtle.digest('SHA-256', strBytes(s)).then(function (buf) {
      return 's2:' + toHex(new Uint8Array(buf));
    }, function () { return 's1:' + djb2(s); });
  }
  return Promise.resolve('s1:' + djb2(s));
}
function meAuth() {
  if (meUser) { logout(); return; }
  showRegGate();
}
/* ---------- 语言切换（中文 / English） ---------- */
var APP_VERSION = 'v1.7.7';
function renderLangSeg() {
  var cur = (window.FuleyI18N && window.FuleyI18N.lang()) || 'zh';
  var html = '';
  [['zh', '中文'], ['en', 'English']].forEach(function (it) {
    html += '<button class="' + (cur === it[0] ? 'on' : '') + '" onclick="switchLang(\'' + it[0] + '\')">' + it[1] + '</button>';
  });
  var box = document.getElementById('langSeg');
  if (box) box.innerHTML = html;
  var ver = document.getElementById('appVer');
  if (ver) ver.textContent = APP_VERSION;
}
function switchLang(l) {
  if (window.FuleyI18N) window.FuleyI18N.switchLang(l);
}
function renderMe() {
  document.getElementById('meUname').textContent = meUser ? meUser.name : L('未登录', 'Not signed in');
  document.getElementById('meUsub').textContent = meUser
    ? L('账号 ' + meUser.account + ' · 数据仅保存在本机', 'Account ' + meUser.account + ' · data stays on this device')
    : '';
  document.getElementById('meAuthBtn').textContent = meUser ? L('登出', 'Sign out') : (loadAccount() ? L('登录', 'Sign in') : L('注册', 'Sign up'));
  document.getElementById('meAvatar').textContent = meUser ? meUser.name.charAt(0) : '浮';
}
function openAuthSheet() {
  var isReg = authMode === 'register';
  sheetMode = 'auth';
  document.getElementById('sheetSave').textContent = isReg ? '注册' : '登录';
  document.getElementById('sheetTitle').textContent = isReg ? '注册浮乐账号' : '登录浮乐';
  var body = '';
  if (isReg) {
    body += '<div class="field"><label>账号（3-20 位字母 / 数字 / 下划线）</label><input type="text" id="auAccount" maxlength="20" placeholder="如 fuley2026" autocomplete="off"></div>'
      + '<div class="field"><label>昵称</label><input type="text" id="auName" maxlength="20" placeholder="怎么称呼你"></div>';
  } else {
    body += '<div class="field"><label>账号</label><input type="text" id="auAccount" maxlength="20" placeholder="请输入账号" autocomplete="off"></div>';
  }
  body += '<div class="field"><label>密码（6-32 位，仅字母 / 数字）</label><input type="password" id="auPass" maxlength="32" placeholder="••••••"></div>';
  if (isReg) {
    body += '<div class="field"><label>确认密码</label><input type="password" id="auPass2" maxlength="32" placeholder="再输一次"></div>';
  }
  body += '<div class="field"><button class="btn ghost btn-block" onclick="authMode=\'' + (isReg ? 'login' : 'register') + '\';openAuthSheet()">'
    + (isReg ? '已有账号？去登录' : '没有账号？去注册') + '</button></div>';
  document.getElementById('sheetBody').innerHTML = body;
  showSheet();
}
function doRegister() {
  var account = (document.getElementById('auAccount').value || '').trim();
  var name = (document.getElementById('auName').value || '').trim();
  var p1 = document.getElementById('auPass').value || '';
  var p2 = document.getElementById('auPass2').value || '';
  if (!/^[a-zA-Z0-9_]{3,20}$/.test(account)) { toast(L('账号需 3-20 位字母 / 数字 / 下划线', 'Account must be 3-20 letters / digits / underscores')); return; }
  if (!name) { toast(L('请填写昵称', 'Please enter a nickname')); return; }
  if (!/^[a-zA-Z0-9]{6,32}$/.test(p1)) { toast(L('密码需 6-32 位，仅含字母和数字', 'Password must be 6-32 letters or digits')); return; }
  if (p1 !== p2) { toast(L('两次密码不一致', 'Passwords do not match')); return; }
  var exist = loadAccount();
  if (exist && exist.account === account) { toast(L('该账号已注册，请直接登录', 'This account is already registered — please sign in')); authMode = 'login'; renderRegGate(); return; }
  hashPass(p1).then(function (h) {
    var acc = { account: account, name: name, algo: h.slice(0, 2), hash: h.slice(3) };
    saveJSON(ACCOUNT_KEY, acc);
    saveJSON(SESSION_KEY, { account: account, name: name });
    meUser = { account: account, name: name };
    renderMe();
    closeSheet();
    toast(L('注册成功，已登录', 'Signed up and signed in'));
    hideRegGate();
    showTrialWelcome();
  });
}
/* ---------- 找回密码：统一走注册卡片的 forgot 模式 ---------- */
function openForgotSheet() { rgForgot(); }
function saveForgotForm() { rgForgotSubmit(); }
function doSignIn() {
  var account = (document.getElementById('auAccount').value || '').trim();
  var p1 = document.getElementById('auPass').value || '';
  var acc = loadAccount();
  if (!acc || acc.account !== account) { toast(L('账号不存在，请先注册', 'Account not found — please sign up')); return; }
  hashPass(p1).then(function (h) {
    if ((acc.algo + ':' + acc.hash) !== h && acc.hash !== h) { toast(L('密码不正确', 'Incorrect password')); return; }
    saveJSON(SESSION_KEY, { account: account, name: acc.name });
    meUser = { account: account, name: acc.name };
    renderMe();
    closeSheet();
    toast(L('登录成功', 'Signed in'));
    hideRegGate();
  });
}
function logout() {
  meUser = null;
  lsDel(SESSION_KEY);
  renderMe();
  // 登出后立即回到注册/登录门，未登录不可查看 App 内容
  showRegGate();
  toast(L('已退出登录', 'Signed out'));
}

/* ---------- 首次打开注册门 + 试用提示 + 最后一周每日提醒 ---------- */
var TRIAL_NOTICE_KEY = 'fuley.trialNotice.v1';
var tnActivateFlag = false;
function licState() {
  if (window.FuleyLicense && window.FuleyLicense.state) return window.FuleyLicense.state();
  return { status: 'trial', daysLeft: 27, expireDate: '', trial: true, licensed: false, valid: true };   // license.js 缺失时的兜底（仅模型）
}
function todayKey() { var d = new Date(); return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }
function showRegGate() {
  authMode = loadAccount() ? 'login' : 'register';
  renderRegGate();
  var tb = document.getElementById('topbar');
  if (tb) tb.style.display = 'none';   // 登录页不显示顶栏
  var g = document.getElementById('regGate');
  var guarded = document.documentElement.hasAttribute('data-gate');
  if (guarded) g.classList.add('instant');   // 守卫接管：不要淡入
  g.classList.add('on');
  // 首屏防闪标记已由真正的 gate 接管，可移除
  try { document.documentElement.removeAttribute('data-gate'); } catch (e) { /* ignore */ }
  if (guarded) setTimeout(function () { g.classList.remove('instant'); }, 80);
}
function hideRegGate() {
  document.getElementById('regGate').classList.remove('on');
  try { document.documentElement.removeAttribute('data-gate'); } catch (e) { /* ignore */ }
  var tb = document.getElementById('topbar');
  if (tb) tb.style.display = '';   // 恢复顶栏
}
function renderRegGate() {
  var isForgot = authMode === 'forgot';
  var isReg = authMode === 'register';
  document.getElementById('rgTitle').textContent = isForgot
    ? L('找回密码', 'Reset password')
    : isReg ? L('欢迎使用浮乐', 'Welcome to Fuley') : L('登录浮乐', 'Sign in to Fuley');
  document.getElementById('rgSub').textContent = isForgot
    ? L('通过注册时的账号与昵称验证身份，验证通过后可设置新密码', 'Verify with the account and nickname you registered, then set a new password')
    : isReg
      ? L('注册账号后即可使用 · 数据仅保存在本机', 'Sign up to start · data stays on this device')
      : L('欢迎回来，登录后继续使用', 'Welcome back, sign in to continue');
  // 注册门上的语言切换按钮
  var lbox = document.getElementById('rgLang');
  if (lbox) {
    var curL = (window.FuleyI18N && window.FuleyI18N.lang()) || 'zh';
    lbox.innerHTML = [['zh', '中文'], ['en', 'English']].map(function (it) {
      return '<button type="button" class="' + (curL === it[0] ? 'on' : '') + '" onclick="switchLang(\'' + it[0] + '\')">' + it[1] + '</button>';
    }).join('');
  }
  var f = '';
  if (isForgot) {
    // 找回密码直接内嵌在注册门卡片里（此前用底部弹层，会被登录遮罩盖住 → 点击像没反应）
    f += '<div class="field"><label>' + L('账号', 'Account') + '</label><input type="text" id="auAccount" maxlength="20" placeholder="' + L('请输入注册账号', 'Your account') + '" autocomplete="off"></div>'
      + '<div class="field"><label>' + L('昵称', 'Nickname') + '</label><input type="text" id="auName" maxlength="20" placeholder="' + L('注册时填写的昵称', 'Nickname used at sign-up') + '"></div>'
      + '<div class="field"><label>' + L('新密码（6-32 位，仅字母 / 数字）', 'New password (6-32 chars, letters / digits)') + '</label><input type="password" id="auPass" maxlength="32" placeholder="••••••"></div>'
      + '<div class="field"><label>' + L('确认新密码', 'Confirm new password') + '</label><input type="password" id="auPass2" maxlength="32" placeholder="' + L('再输一次', 'Enter again') + '"></div>'
      + '<button class="btn" onclick="rgForgotSubmit()">' + L('重置密码', 'Reset password') + '</button>';
  } else {
    if (isReg) {
      f += '<div class="field"><label>' + L('账号（3-20 位字母 / 数字 / 下划线）', 'Account (3-20 letters / digits / underscore)') + '</label><input type="text" id="auAccount" maxlength="20" placeholder="' + L('如 fuley2026', 'e.g. fuley2026') + '" autocomplete="off"></div>'
        + '<div class="field"><label>' + L('昵称', 'Nickname') + '</label><input type="text" id="auName" maxlength="20" placeholder="' + L('怎么称呼你', 'What should we call you') + '"></div>';
    } else {
      f += '<div class="field"><label>' + L('账号', 'Account') + '</label><input type="text" id="auAccount" maxlength="20" placeholder="' + L('请输入账号', 'Enter your account') + '" autocomplete="off"></div>';
    }
    f += '<div class="field"><label>' + L('密码（6-32 位，仅字母 / 数字）', 'Password (6-32 chars, letters / digits)') + '</label><input type="password" id="auPass" maxlength="32" placeholder="••••••"></div>';
    if (isReg) f += '<div class="field"><label>' + L('确认密码', 'Confirm password') + '</label><input type="password" id="auPass2" maxlength="32" placeholder="' + L('再输一次', 'Enter again') + '"></div>';
    f += '<button class="btn" onclick="rgSubmit()">' + (isReg ? L('注册并开始', 'Sign Up & Start') : L('登录', 'Sign In')) + '</button>';
  }
  document.getElementById('rgForm').innerHTML = f;
  document.getElementById('rgSwitch').innerHTML = isForgot
    ? '<a onclick="authMode=\'login\';renderRegGate()">' + L('返回登录', 'Back to sign in') + '</a>'
    : isReg
      ? L('已有账号？<a onclick="authMode=\'login\';renderRegGate()">去登录</a>', 'Have an account? <a onclick="authMode=\'login\';renderRegGate()">Sign in</a>')
      : L('没有账号？<a onclick="authMode=\'register\';renderRegGate()">去注册</a>', 'No account? <a onclick="authMode=\'register\';renderRegGate()">Sign up</a>')
        + ' · <a onclick="rgForgot()">' + L('忘记密码？', 'Forgot password?') + '</a>';
}
/* 忘记密码：切到注册卡片内的 forgot 模式（不再用底部弹层，避免被遮罩挡住） */
function rgForgot() {
  if (!loadAccount()) { toast(L('本机还没有注册账号，请先注册', 'No account on this device — please sign up first')); authMode = 'register'; renderRegGate(); return; }
  authMode = 'forgot'; renderRegGate();
}
function rgForgotSubmit() {
  var acc = loadAccount();
  if (!acc) { toast(L('本机还没有注册账号', 'No account on this device')); return; }
  var account = (document.getElementById('auAccount').value || '').trim();
  var name = (document.getElementById('auName').value || '').trim();
  var p1 = document.getElementById('auPass').value || '';
  var p2 = document.getElementById('auPass2').value || '';
  if (account !== acc.account) { toast(L('账号与本机注册的账号不一致', 'Account does not match this device')); return; }
  if (name !== (acc.name || '')) { toast(L('昵称不正确，无法验证身份', 'Nickname incorrect — cannot verify')); return; }
  if (!/^[a-zA-Z0-9]{6,32}$/.test(p1)) { toast(L('密码需 6-32 位字母或数字', 'Password must be 6-32 letters or digits')); return; }
  if (p1 !== p2) { toast(L('两次密码不一致', 'Passwords do not match')); return; }
  hashPass(p1).then(function (h) {
    var parts = h.split(':');
    acc.algo = parts[0]; acc.hash = parts[1];
    saveJSON(ACCOUNT_KEY, acc);
    authMode = 'login';
    renderRegGate();
    toast(L('密码已重置，请用新密码登录', 'Password reset — sign in with the new one'));
  });
}
function rgSubmit() { if (authMode === 'register') doRegister(); else doSignIn(); }
function showTrialNotice(opt) {
  opt = opt || {};
  document.getElementById('tnT').textContent = opt.title || L('试用期 30 天', '30-day trial');
  document.getElementById('tnS').innerHTML = opt.body || L('注册成功，欢迎加入浮乐！<br>当前为试用版，有效期 30 天，功能全部开放；到期后输入激活码可授权使用 1 年。',
    'You are in! Welcome to Fuley.<br>You are on a 30-day trial with all features open; after it ends, enter an activation code for a 1-year license.');
  document.getElementById('tnLater').style.display = opt.later ? '' : 'none';
  document.getElementById('tnOk').textContent = opt.okText || L('知道了', 'Got it');
  document.getElementById('trialNotice').classList.add('on');
}
function closeTrialNotice() { document.getElementById('trialNotice').classList.remove('on'); }
function tnOkAct() {
  closeTrialNotice();
  if (tnActivateFlag) { tnActivateFlag = false; openLicense(); }
}
function showTrialWelcome() { tnActivateFlag = false; showTrialNotice({}); }
/* 授权到期提醒：试用剩 ≤7 天、或正式授权剩 ≤15 天，每天提醒一次（按自然日去重） */
function checkTrialDaily() {
  var st = licState();
  if (!st || st.daysLeft <= 0) return;
  var isTrial = st.status === 'trial';
  var warnDays = (window.FuleyLicense && window.FuleyLicense.WARN_DAYS) || 15;
  if (isTrial ? st.daysLeft > 7 : st.daysLeft > warnDays) return;
  if (loadJSON(TRIAL_NOTICE_KEY, '') === todayKey()) return;
  saveJSON(TRIAL_NOTICE_KEY, todayKey());
  tnActivateFlag = true;
  if (isTrial) {
    showTrialNotice({
      title: L('试用期剩余 ' + st.daysLeft + ' 天', st.daysLeft + ' days left in trial'),
      body: L('试用期还剩 <b>' + st.daysLeft + ' 天</b>，到期后将锁定功能。<br>在「我的 - 授权许可」发送设备识别码给作者，获取激活码激活后使用 1 年。',
        '<b>' + st.daysLeft + ' days</b> left in your trial; features lock after that.<br>Send your device ID from Me → License to the author to get a code, then enjoy 1 year.'),
      okText: L('去激活', 'Activate'), later: true
    });
  } else {
    showTrialNotice({
      title: L('授权还有 ' + st.daysLeft + ' 天到期', 'License expires in ' + st.daysLeft + ' days'),
      body: L('当前授权将于 <b>' + (st.expireDate || '') + '</b> 到期，还剩 <b>' + st.daysLeft + ' 天</b>。<br>一年一签，请及时续签以免功能被锁定。',
        'Your license expires on <b>' + (st.expireDate || '') + '</b>, <b>' + st.daysLeft + ' days</b> left.<br>Licenses renew yearly — please renew in time to avoid a lockout.'),
      okText: L('去续签', 'Renew'), later: true
    });
  }
}
function collectData() {
  return {
    app: 'fuley', version: APP_VERSION, exportedAt: new Date().toISOString(),
    plans: plans, signals: signals, notes: notes,
    quiz: quizItems, panic: panicLv, cal: calCustom
  };
}
var lastExportUri = null;
function exportFileName() { return 'fuley-export-' + new Date().toISOString().slice(0, 10) + '.json'; }
function exportCount() { return plans.length + signals.length + notes.red.length + notes.green.length + notes.case.length; }
function b64ofJson(s) {
  try { return btoa(unescape(encodeURIComponent(s))); } catch (e) { return btoa(s); }
}
function webDownload(json, name, cnt) {
  var blob = new Blob([json], { type: 'application/json' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(function () { URL.revokeObjectURL(a.href); }, 1000);
  toast(L('已导出 ' + cnt + ' 条 · 已保存到浏览器下载目录', 'Exported ' + cnt + ' items · saved to browser downloads'));
}
/* 原生 App：写进「文档」目录（文件管理器可见），并打开分享面板可直接保存/发送 */
function exportData() {
  var data = collectData();
  var json = JSON.stringify(data, null, 2);
  var name = exportFileName();
  var cnt = exportCount();
  var nat = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  var FS = nat && window.Capacitor.Plugins && window.Capacitor.Plugins.Filesystem;
  if (FS && FS.writeFile) {
    FS.writeFile({ path: name, data: b64ofJson(json), directory: 'DOCUMENTS', recursive: true })
      .then(function (res) {
        lastExportUri = res && res.uri ? res.uri : null;
        var row = document.getElementById('shareExportRow');
        if (row && lastExportUri) row.style.display = '';
        var shown = lastExportUri ? String(lastExportUri).replace(/^file:\/\//, '') : name;
        toast(L('已导出 ' + cnt + ' 条 · 保存在「文档」目录：' + shown, 'Exported ' + cnt + ' items · Documents/' + shown));
        var SH = window.Capacitor.Plugins && window.Capacitor.Plugins.Share;
        if (SH && SH.share && lastExportUri) {
          SH.share({ title: name, text: '浮乐数据导出', url: lastExportUri, dialogTitle: L('导出文件 · 可保存或发送', 'Export file · save or send') })
            .catch(function () { /* 用户取消 */ });
        }
      })
      .catch(function () { webDownload(json, name, cnt); });
    return;
  }
  webDownload(json, name, cnt);
}
function shareExport() {
  var SH = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Share;
  if (!lastExportUri || !SH || !SH.share) { toast(L('还没有可分享的导出文件', 'No export to share')); return; }
  SH.share({ title: exportFileName(), text: '浮乐数据导出', url: lastExportUri, dialogTitle: L('导出文件 · 可保存或发送', 'Export file · save or send') })
    .catch(function () {});
}

/* 备份：本机应用存储各存一份，原生端同时写入「文档」目录（同名自动覆盖，toast 提示路径） */
function backupFileName() { return 'fuley-backup-' + new Date().toISOString().slice(0, 10) + '.json'; }
function backupData() {
  var json = JSON.stringify(collectData());
  try {
    lsSet('fuley_backup', json);
    document.getElementById('backupState').textContent = '刚刚已备份';
  } catch (e) {
    toast('备份失败：' + e.message);
    return;
  }
  var nat = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  var FS = nat && window.Capacitor.Plugins && window.Capacitor.Plugins.Filesystem;
  if (FS && FS.writeFile) {
    FS.writeFile({ path: backupFileName(), data: b64ofJson(json), directory: 'DOCUMENTS', recursive: true })
      .then(function (res) {
        var shown = res && res.uri ? String(res.uri).replace(/^file:\/\//, '') : backupFileName();
        toast(L('备份成功 · 保存在「文档」目录：' + shown, 'Backup saved · Documents/' + shown));
      })
      .catch(function () {
        toast(L('备份成功（仅本机应用存储）', 'Backup saved locally'));
      });
    return;
  }
  toast(L('备份成功，保存在本机应用存储', 'Backup saved on this device'));
}
function pickRestoreFile() {
  document.getElementById('restoreFile').click();
}
function restoreData(input) {
  var f = input.files && input.files[0];
  if (!f) return;
  if (!window.confirm('恢复将用备份文件覆盖当前数据，确定继续？')) { input.value = ''; return; }
  var r = new FileReader();
  r.onload = function () {
    try {
      var d = JSON.parse(r.result);
      if (!d || typeof d !== 'object') throw new Error('格式不符');
      if (Array.isArray(d.plans)) { plans = d.plans; savePlans(); }
      if (Array.isArray(d.signals)) { signals = d.signals; saveSignals(); }
      if (d.notes && typeof d.notes === 'object') {
        notes = { red: d.notes.red || [], green: d.notes.green || [], case: d.notes.case || [] };
        saveNotes();
      }
      if (Array.isArray(d.quiz) && d.quiz.length) { quizItems = d.quiz; saveQuiz(); }
      if (d.panic != null) { panicLv = Math.min(10, Math.max(0, Number(d.panic) || 0)); lsSet(PANIC_KEY, String(panicLv)); }
      if (Array.isArray(d.cal)) { calCustom = d.cal; saveCalCustom(); }
      renderPlans(); renderSignals(); renderNotes(); renderQuiz(); renderPanic(); renderCal();
      var cnt = plans.length + signals.length + notes.red.length + notes.green.length + notes.case.length;
      toast('恢复成功，共 ' + cnt + ' 条');
    } catch (e) {
      toast('备份文件无效，恢复失败');
    }
    input.value = '';
  };
  r.readAsText(f);
}

/* ---------- Toast ---------- */
function toast(msg) {
  var root = document.getElementById('toastRoot');
  if (!root) { return; }
  var t = document.createElement('div');
  t.className = 'toast';
  t.textContent = msg;
  root.appendChild(t);
  setTimeout(function () {
    t.classList.add('out');
    setTimeout(function () { if (t.parentNode) t.parentNode.removeChild(t); }, 280);
  }, 1800);
}

/* ---------- 启动 ---------- */
(function init() {
  applyTheme(lsGet(THEME_KEY) === 'dark' ? 'dark' : 'light');

  // 授权（deviceId / 试用记录 / 到期锁定）
  if (window.FuleyLicense) {
    window.FuleyLicense.init();
    renderLicenseState();
  }

  // 事件绑定
  document.querySelectorAll('#tabbar .tab').forEach(function (t) {
    t.addEventListener('click', function () { switchTab(t); });
  });
  document.getElementById('fab').addEventListener('click', openSheet);
  document.getElementById('themeBtn').addEventListener('click', toggleTheme);
  document.getElementById('refreshBtn').addEventListener('click', function () {
    var b = this;
    b.classList.add('spin');
    refreshQuotes().then(function () { b.classList.remove('spin'); }, function () { b.classList.remove('spin'); });
  });
  document.getElementById('cfClose').addEventListener('click', closeChartFull);
  document.getElementById('cfReset').addEventListener('click', resetChartFull);
  document.getElementById('backdrop').addEventListener('click', closeSheet);
  document.getElementById('restoreFile').addEventListener('change', function () { restoreData(this); });
  document.getElementById('noteInput').addEventListener('input', function () {
    document.getElementById('noteCount').textContent = this.value.length + ' / 500';
  });

  // 恢复登录会话：无会话 → 首次打开注册门（阻塞）；有会话 → 试用最后一周每日提醒
  var s = loadSession();
  if (s && s.account) { meUser = s; checkTrialDaily(); } else { showRegGate(); }
  document.addEventListener('visibilitychange', function () { if (!document.hidden) checkTrialDaily(); });

  // 恢复上次所在页（语言切换 reload 后不跳回首页）
  (function () {
    if (curTab !== 'home') {
      var tb = document.querySelector('.tab[data-tab="' + curTab + '"]');
      if (tb) switchTab(tb);
    }
  })();

  // 初始渲染
  renderMe();
  renderLangSeg();
  renderIndices();
  renderIdxStrip();
  renderPlans();
  syncPosTune();
  renderPosRatio();
  renderSignals();
  renderNotes();
  renderQuiz();
  renderPanic();
  renderCal();
  if (curTab === 'signals') { renderQuiz(); }

  // 定投通知重排（重启 / 数据恢复后）
  if (hasLN()) {
    ensureNotifyPermission().then(function () {
      plans.forEach(function (p) { schedulePlanNotify(p); });
      // 财报通知重排：已设提醒的日期重新挂上系统通知
      earnRemind.forEach(function (r) {
        var e = EARN.filter(function (x) { return x.c === r.c && x.d === r.d; })[0];
        if (e) scheduleEarnNotify(e);
      });
    });
  }

  // 行情：立即拉一次 + 60s 自动刷新
  refreshQuotes();
  setInterval(refreshQuotes, 60000);
  // 从后台切回时立即刷新一次（10s 节流）：回到 App 即可看到最新行情，不受网络类型影响
  var lastVisRefresh = 0;
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState !== 'visible') return;
    var now = Date.now();
    if (now - lastVisRefresh < 10000) return;
    lastVisRefresh = now;
    refreshQuotes();
  });

  // VIX 仪表盘：恢复缓存 → 渲染 → 原生环境增量拉取 FRED
  vixRestore();
  renderVix();
  vixFetchUpdate();
  renderEconCycle();
  renderGold();
  // 黄金：518880 日 K / 分时拉取（失败则用内置快照）

  // Service Worker（PWA 离线可用；Capacitor 原生环境无 SW 时静默跳过）
  if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol)) {
    navigator.serviceWorker.register('sw.js').catch(function () { /*  ignore */ });
  }
})();

/* ---------- 加减仓法则（交互式金字塔，与页面模型一致） ---------- */
function IS_EN() { return !!(window.FuleyI18N && window.FuleyI18N.isEn && window.FuleyI18N.isEn()); }
(function () {
  // trigs: 各档触发涨跌幅（正数，加仓=跌幅、减仓=涨幅；0=建仓起点）
  // ratios: 各档买入/卖出比例（占总预算 / 期初持仓的 %）
  var MODES = {
    add:  { laws: ['先定这只标的的总预算，再排档位；至少分 4 档，别两三次打完', '永远不满仓：留 30% 现金，总仓位 80% 以上停止加仓'],
          rec: '建议 <b>4–8 档</b>：第 1 档建仓，之后以建仓价为基准每跌 5%–10% 加一档，越跌买越多。例：10 万预算按 1/2/3/4 万递增排 4 档。',
          tag: '应对下跌（正金字塔加仓）', hint: '以建仓价为起点设跌幅阈值，第 1 档建底仓，每跌一档买得更多，低位重仓摊薄成本。比例是各档买入金额占总预算的 %。',
          verb: '跌', act: '补', secT: '各档触发与买入比例（以建仓价为起点）', unit1: '跌幅%', unit2: '买入%',
            trigs: [0, 5, 10, 15], ratios: [10, 20, 30, 40], color: '#e04a4a' },
    trim: { laws: ['越涨越卖时先收回本金，卖到成本出清后，剩下的仓位才是利润在跑', '跌破启动价（或回撤 10%）就停止卖出计划，别把底部筹码也交出去'],
          rec: '建议 <b>3–4 档</b>：以建仓价（底部）为基准，每涨 5%–10% 卖一档，累计涨 20% 以上清到只剩底仓。',
          tag: '应对上涨（倒金字塔减仓）', hint: '以建仓价为起点设涨幅阈值，越高卖得越多，先收回本金，最后只留底仓跟随行情。比例是各档卖出量占期初持仓的 %。',
          verb: '涨', act: '卖', secT: '各档触发与卖出比例（以建仓价为起点）', unit1: '涨幅%', unit2: '卖出%',
            trigs: [5, 10, 15, 20], ratios: [10, 20, 30, 30], color: '#4a7fd4' }
  };
  var PYR_KEY = 'fuley.pyr.v1';
  var saved = loadJSON(PYR_KEY, null) || {};
  function freshMode(m) {
    return { trigs: MODES[m].trigs.slice(), ratios: MODES[m].ratios.slice(), laws: MODES[m].laws.slice() };
  }
  var state = { add: freshMode('add'), trim: freshMode('trim') };
  // 恢复已保存的档位 / 比例 / 纪律（长度与数值不合法的部分回退默认）
  ['add', 'trim'].forEach(function (m) {
    var d = saved[m];
    if (!d || typeof d !== 'object') return;
    if (Array.isArray(d.trigs) && Array.isArray(d.ratios) &&
        d.trigs.length === d.ratios.length && d.trigs.length >= 2 && d.trigs.length <= 10) {
      var okT = d.trigs.every(function (x) { return isFinite(Number(x)) && Number(x) >= 0; });
      var okR = d.ratios.every(function (x) { return isFinite(Number(x)); });
      if (okT && okR) {
        state[m].trigs = d.trigs.map(Number);
        state[m].ratios = d.ratios.map(Number);
      }
    }
    if (Array.isArray(d.laws) && d.laws.length) state[m].laws = d.laws.map(String);
  });
  var cur = (saved.mode === 'trim') ? 'trim' : 'add';
  var trigs = state[cur].trigs, ratios = state[cur].ratios;
  function savePyr() { saveJSON(PYR_KEY, { mode: cur, add: state.add, trim: state.trim }); }

  window.bSetMode = function (m) {
    if (m !== 'add' && m !== 'trim') return;
    cur = m;
    trigs = state[m].trigs; ratios = state[m].ratios;
    document.querySelectorAll('#bseg button').forEach(function (b) {
      b.classList.toggle('on', b.getAttribute('data-m') === m);
    });
    document.getElementById('bSecT').textContent = MODES[m].secT;
    savePyr();
    bRender(); bSyncCycle();
  };
  window.bSyncCycle = function () {
    document.getElementById('cyAdd').classList.toggle('on', cur === 'add');
    document.getElementById('cyTrim').classList.toggle('on', cur === 'trim');
    document.getElementById('cyArcDown').classList.toggle('dim', cur === 'trim');
    document.getElementById('cyArcUp').classList.toggle('dim', cur === 'add');
  };
  window.bReset = function () {
    state[cur].trigs = MODES[cur].trigs.slice();
    state[cur].ratios = MODES[cur].ratios.slice();
    trigs = state[cur].trigs; ratios = state[cur].ratios;
    savePyr();
    bRender();
    toast(L('已恢复默认档位', 'Tiers reset to default'));
  };
  window.bAddTier = function (d) {
    var n = ratios.length + d;
    if (n < 2 || n > 10) return;
    if (d > 0) {
      var lastT = trigs[trigs.length - 1];
      var lastR = ratios[ratios.length - 1];
      // 新档默认：触发递增一档（默认步长 5），比例继承末档，均可直接改
      trigs.push(lastT === 0 ? 5 : lastT + 5);
      ratios.push(lastR || 10);
    } else {
      trigs.pop(); ratios.pop();
    }
    savePyr();
    bRender();
  };
  window.bSetTrig = function (i, v) {
    var x = parseFloat(v);
    trigs[i] = isFinite(x) && x >= 0 ? x : 0;
    savePyr();
    bRender(true);
  };
  window.bSetRatio = function (i, v) {
    var x = parseFloat(v);
    ratios[i] = isFinite(x) && x > 0 ? x : 0;
    savePyr();
    bRender(true);
  };

  /* 纪律：默认文案可能被翻译层改写，用 raw 标记保护；保存时去掉标记 */
  function rawTxt(t) {
    var v = String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return (window.FuleyI18N && window.FuleyI18N.raw) ? window.FuleyI18N.raw(v) : v;
  }
  function stripMark(t) { return String(t == null ? '' : t).replace(/[\uE000\uE001]/g, ''); }

  window.bSetLaw = function (i, txt) {
    var arr = state[cur].laws;
    if (i < 0 || i >= arr.length) return;
    var v = stripMark(txt).replace(/\s+/g, ' ').trim();
    if (v === stripMark(arr[i])) return;      // 未改动
    arr[i] = v;
    savePyr();
    toast(L('纪律已保存', 'Rule saved'));
  };
  window.bAddLaw = function () {
    state[cur].laws.push('');
    savePyr();
    bRender();
    var box = document.getElementById('bLaws');
    var items = box.querySelectorAll('.bc-tx');
    var last = items[items.length - 1];
    if (last) {
      last.focus();
      var r = document.createRange(); r.selectNodeContents(last);
      var sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(r);
    }
  };
  window.bDelLaw = function (i) {
    var arr = state[cur].laws;
    if (i < 0 || i >= arr.length) return;
    arr.splice(i, 1);
    savePyr();
    bRender();
    toast(L('已删除该条纪律', 'Rule removed'));
  };

  window.bRender = function (keepFocus) {
    var m = MODES[cur];
    var n = ratios.length;
    var max = Math.max.apply(null, ratios.concat([1]));
    var sum = ratios.reduce(function (a, b) { return a + b; }, 0);

    document.getElementById('bhint').textContent = m.tag + ' · ' + m.hint;
    document.getElementById('bN').textContent = n;
    document.getElementById('bRec').innerHTML = m.rec;
    var laws = state[cur].laws;
    var en = IS_EN();
    document.getElementById('bLawT').textContent = m.tag + ' · ' +
      (en ? 'Discipline (' + laws.length + ')' : '纪律（' + laws.length + ' 条）');
    var lbox = document.getElementById('bLaws');
    lbox.innerHTML = laws.map(function (t, i) {
      return '<div class="bc-law"><span class="bc-no">' + (i + 1) + '</span>'
        + '<span class="bc-tx" contenteditable="true" data-i="' + i + '" spellcheck="false">' + rawTxt(t) + '</span>'
        + '<button class="bc-del" data-i="' + i + '" title="' + (en ? 'Delete' : '删除') + '">×</button></div>';
    }).join('');
    [].forEach.call(lbox.querySelectorAll('.bc-tx'), function (el) {
      el.addEventListener('blur', function () { bSetLaw(Number(el.getAttribute('data-i')), el.textContent); });
      el.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') { e.preventDefault(); el.blur(); }
      });
    });
    [].forEach.call(lbox.querySelectorAll('.bc-del'), function (btn) {
      btn.addEventListener('click', function (e) { e.stopPropagation(); bDelLaw(Number(btn.getAttribute('data-i'))); });
    });

    // 展示顺序：加仓为正常金字塔（顶尖朝上）；减仓倒置，使最大档在最上方、尖端朝下
    var disp = ratios.slice();
    if (cur === 'trim') disp.reverse();
    var w = disp.map(function (r) { return Math.max(0.34, r / max); });
    // 边界宽度：正常金字塔顶端收尖；倒金字塔底端收尖
    var B = w.slice();
    if (cur === 'add') B.unshift(0); else B.push(0);

    var f = '';
    for (var i = 0; i < n; i++) {
      var srcIdx = (cur === 'trim') ? (n - 1 - i) : i;
      var pct = ratios[srcIdx];
      var tg = trigs[srcIdx];
      var trigTxt = (tg === 0) ? '建仓' : ((cur === 'trim' ? '+' : '-') + tg.toFixed(0) + '%');
      var t = B[i] * 100, b = B[i + 1] * 100;
      var clip = 'polygon(' + (50 - t / 2).toFixed(2) + '% 0,' + (50 + t / 2).toFixed(2) + '% 0,'
        + (50 + b / 2).toFixed(2) + '% 100%,' + (50 - b / 2).toFixed(2) + '% 100%)';
      var labCls = 'bt-lab';
      if (i === 0 && cur === 'add') labCls += ' bot';
      if (i === n - 1 && cur === 'trim') labCls += ' top';
      f += '<div class="btier">'
        + '<div class="bt-bg" style="clip-path:' + clip + ';background:linear-gradient(180deg,rgba(255,255,255,.16),rgba(0,0,0,.05)),' + m.color + '"></div>'
        + '<div class="' + labCls + '">' + (tg === 0 ? '' : '<span class="bt-no">' + (IS_EN() ? 'Tier ' + (srcIdx + 1) + ' · ' + trigTxt : '第 ' + (srcIdx + 1) + ' 档 · ' + trigTxt) + '</span>') + '<span class="bt-pc">' + pct.toFixed(0) + '%</span></div>'
        + '</div>';
    }
    var cap = (cur === 'add')
      ? '塔尖第 1 层 = 建仓（0%），越往下跌幅越大、买得越多'
      : '塔底为建仓价 0% 起点，越往上涨幅越大、卖得越多';
    document.getElementById('bfig').innerHTML = '<div class="bpyr">' + f + '</div><div class="pcap">' + cap + '</div>';

    // 逐档编辑表：档位 | 触发% | 比例%
    var e = '<div class="btr bth"><span class="bth1">档位</span><span class="bth2">' + m.unit1 + '</span><span class="bthu"></span><span class="bth2">' + m.unit2 + '</span><span class="bthu"></span></div>';
    for (var k = 0; k < n; k++) {
      var noTxt = (cur === 'add' && k === 0) ? (IS_EN() ? 'Tier 1<i>open</i>' : '第 1 档<i>建仓</i>') : ((IS_EN() ? 'Tier ' + (k + 1) : '第 ' + (k + 1) + ' 档'));
      e += '<div class="btr">'
        + '<span class="bno">' + noTxt + '</span>'
        + '<input type="number" min="0" step="0.5" value="' + trigs[k] + '" onchange="bSetTrig(' + k + ',this.value)">'
        + '<span class="bunit">%</span>'
        + '<input type="number" min="0" step="1" value="' + ratios[k] + '" onchange="bSetRatio(' + k + ',this.value)">'
        + '<span class="bunit">%</span>'
        + '</div>';
    }
    document.getElementById('bratio').innerHTML = '<div class="btab">' + e + '</div>';

    var sumTxt;
    if (cur === 'add') {
      sumTxt = (IS_EN() ? 'Total <b>' + n + '</b> tiers (incl. open) · budget <b>' + sum + '%</b>'
               : '共 <b>' + n + '</b> 档（含建仓）· 预算合计 <b>' + sum + '%</b>')
        + (sum < 99.5 ? (IS_EN() ? ' · <b>' + (100 - sum).toFixed(0) + '%</b> cash left'
            : ' · 还剩 <b>' + (100 - sum).toFixed(0) + '%</b> 现金')
           : (sum > 100.5 ? (IS_EN() ? ' · <span class="warn">over budget, lower it</span>'
            : ' · <span class="warn">超出预算，请调低</span>') : (IS_EN() ? ' · budget fully allocated' : ' · 预算全部排完')));
    } else {
      sumTxt = (IS_EN() ? 'Total <b>' + n + '</b> tiers · cumulative sold <b>' + sum + '%</b> · keep <b>' + Math.max(0, 100 - sum).toFixed(0) + '%</b> core'
               : '共 <b>' + n + '</b> 档 · 累计卖出 <b>' + sum + '%</b> 持仓 · 保留 <b>' + Math.max(0, 100 - sum).toFixed(0) + '%</b> 底仓')
        + (sum > 100.5 ? (IS_EN() ? ' · <span class="warn">exceeds holding, lower it</span>' : ' · <span class="warn">超过持仓，请调低</span>') : '');
    }
    document.getElementById('bsum').innerHTML = sumTxt;
  };

  document.getElementById('bSecT').textContent = MODES[cur].secT;
  document.querySelectorAll('#bseg button').forEach(function (b) {
    b.classList.toggle('on', b.getAttribute('data-m') === cur);
  });
  bSyncCycle();
  bRender();
})();
